-- Repeatable Flyway migration generated from the pfla-data Liquibase changelogs.
-- Scope:
--   REPORT_OUTPUT_TYPES, ROLES, REPORTS, REPORT_QUERIES,
--   FIELD_ATTRIBUTES, REPORT_ROLES
--
-- The source changelogs contain SYSDATE for report creation dates. CURRENT_DATE
-- is used for newly inserted reports, while existing report creation dates are
-- deliberately preserved on conflict so rerunning this repeatable migration
-- does not change them.
--

BEGIN;

-- REPORT_OUTPUT_TYPES

    ON CONFLICT (id) DO UPDATE SET
    extension = EXCLUDED.extension,
                            description = EXCLUDED.description;

-- ROLES

    ON CONFLICT (role_id) DO UPDATE SET
    role_name = EXCLUDED.role_name;

-- REPORTS

    ON CONFLICT (id) DO UPDATE SET
    description = EXCLUDED.description,
                            name = EXCLUDED.name,
                            file_name = EXCLUDED.file_name,
                            template_secure_document_id = EXCLUDED.template_secure_document_id,
                            num_days_to_keep = EXCLUDED.num_days_to_keep,
                            report_output_type = EXCLUDED.report_output_type,
                            report_owner_id = EXCLUDED.report_owner_id,
                            report_owner_name = EXCLUDED.report_owner_name,
                            report_owner_email = EXCLUDED.report_owner_email,
                            active = EXCLUDED.active;

-- REPORT_QUERIES

    ON CONFLICT (id) DO UPDATE SET
    report_id = EXCLUDED.report_id,
                            query = EXCLUDED.query,
                            tab_name = EXCLUDED.tab_name,
                            "index" = EXCLUDED."index";

-- FIELD_ATTRIBUTES

    ON CONFLICT (id) DO UPDATE SET
    report_query_id = EXCLUDED.report_query_id,
                            source_name = EXCLUDED.source_name,
                            mapped_name = EXCLUDED.mapped_name,
                            format = EXCLUDED.format,
                            format_type = EXCLUDED.format_type,
                            column_width = EXCLUDED.column_width,
                            column_order = EXCLUDED.column_order;

-- REPORT_ROLES

    ON CONFLICT (report_id, role_id) DO NOTHING;

COMMIT;
